// The usable digest issue number off a bridge payload — null when the
// payload carries no positive issue number (a bridge error body, gh-1371).
function digestNumberOf(payload) {
   var n = payload && payload.number;
   if (typeof n === 'number' && isFinite(n) && n > 0) return n;
   if (typeof n === 'string' && n.trim() !== '' && isFinite(Number(n))) return Number(n);
   return null;
}

// Files the digest (or reuses the probed one); a createIssue throw — or a
// create response without a usable issue number — throws through: the
// merge defers rather than resolving threads against a nonexistent digest
// (gh-1371). The search-then-create probe is racy across the two merge
// funels (gh-1371): a concurrent funnel can file its own digest between
// our probe and our create, so the dedup also runs POST-create — the
// concurrent digest wins, our duplicate is abandoned (digestDuplicate)
// and the `defered` tags converge on ONE digest.
function fileDigest(t, comments, owner, name, input, out, ledger) {
   var probed = probeExistingDigest(t, owner, name, input, out);
   if (probed) {
       out.digest = probed.number;
       out.digestReused = true;
       return probed;
