+    if (!comments) {
+        throw new Error('mergeBackstop: no pr-comments primitive — the ledger append cannot read its base');
+    }
+    var ledger = appendCountedToLedger(ledgerBaseOf(t, inp.prNumber, inp.logins),","path":"js/common/mergeBackstop.js","commit_id":"190d24855df2fa7b5cd2c2d3107b3ae389b75b48","original_commit_id":"190d24855df2fa7b5cd2c2d3107b3ae389b75b48","user":{"login":"dmtools-factory-bot[bot]","id":343968581,"node_id":"BOT_kgDOFICLRQ","avatar_url":"https://avatars.githubusercontent.com/u/854251?v=4","gravatar_id":"","url":"https://api.github.com/users/dmtools-factory-bot%5Bbot%5D","html_url":"https://github.com/apps/dmtools-factory-bot","followers_url":"https://api.github.com/users/dmtools-factory-bot%5Bbot%5D/followers","following_url":"https://api.github.com/users/dmtools-factory-bot%5Bbot%5D/following{/other_user}","gists_url":"https://api.github.com/users/dmtools-factory-bot%5Bbot%5D/gists{/gist_id}","starred_url":"https://api.github.com/users/dmtools-factory-bot%5Bbot%5D/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/dmtools-factory-bot%5Bbot%5D/subscriptions","organizations_url":"https://api.github.com/users/dmtools-factory-bot%5Bbot%5D/orgs","repos_url":"https://api.github.com/users/dmtools-factory-bot%5Bbot%5D/repos","events_url":"https://api.github.com/users/dmtools-factory-bot%5Bbot%5D/events{/privacy}","received_events_url":"https://api.github.com/users/dmtools-factory-bot%5Bbot%5D/received_events","type":"Bot","user_view_type":"public","site_admin":false},"body":"✅ addressed in gh-1371 (fix branch `ai/gh-1371`): the counted path now reads the PR comments ONCE in `runBackstop` (the primitive gate throws on a missing/broken read) and passes the single payload down to `ledgerBaseOf` and to the digest review-run reference. Unit-tested: mergeBackstop gh-1371 findings suite, finding 1 (exactly one comments read per counted run, the ledger append served by the same read).","created_at":"2026-11-05T17:47:25Z","updated_at":"2026-11-05T17:47:25Z","html_url":"https://github.com/IstiN/dmtools-agents/pull/1368#discussion_r4483945776","pull_request_url":